package net.civeira.phylax.feature.observe.observedprobe.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class ExpectedTextVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property expected text of observed probe ")
  void test_expected_text_v_o_builder() {
    Assertions.assertFalse(ExpectedTextVO.nullValue().getExpectedText().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(ExpectedTextVO.tryFrom(null).getExpectedText().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", ExpectedTextVO.from("one").getExpectedText().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> ExpectedTextVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", ExpectedTextVO.from("one").toString());
  }
}
